import json
import os

LINE = 69  # 64 board + 4 castling + 1 ep
EP = 68
OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), 're.json')


def seg_pattern(conds):
    parts = []
    pos = 0
    for i in sorted(conds):
        if i > pos:
            parts.append(('gap', None, '.{%d}' % (i - pos)))
        parts.append(('cond', i, conds[i]))
        pos = i + 1
    return parts, pos


def make_rule(conds, writes):
    """Rule matching the source line (first line) and inserting a new line
    after it with the given writes applied."""
    conds = dict(conds)
    for i in writes:
        conds.setdefault(i, '.')
    parts, pos = seg_pattern(conds)
    if pos < LINE:
        parts.append(('gap', None, '.{%d}' % (LINE - pos)))
    pat = '^'
    src = ''
    new = ''
    gi = {}
    for n, (kind, idx, text) in enumerate(parts, 1):
        pat += '(' + text + ')'
        ref = '\\g<%d>' % n
        src += ref
        if kind == 'cond':
            gi[idx] = ref
    for n, (kind, idx, text) in enumerate(parts, 1):
        ref = '\\g<%d>' % n
        if kind == 'gap':
            new += ref
        elif idx in writes:
            w = writes[idx]
            new += gi[w[1]] if isinstance(w, tuple) else w
        else:
            new += ref
    return [pat, src + '\n' + new]


def anchored(conds):
    parts, _ = seg_pattern(conds)
    return ''.join(t for _, _, t in parts)


def sq(r, f):
    return r * 8 + f


def onb(r, f):
    return 0 <= r < 8 and 0 <= f < 8


TARGET = '[_pnbrq]'
ORTHO = [(-1, 0), (1, 0), (0, -1), (0, 1)]
DIAG = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
KN = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]

rules = []
# ---- parse FEN into fixed-width line: 64 squares + 4 castling + ep file ----
rules += [
    [r' w (\S+) ([a-h])6(?: \d+ \d+)?$', r' \1 \2'],
    [r' w (\S+) -(?: \d+ \d+)?$', r' \1 -'],
    [r' - (\S)$', r'  \1'],
    [r'^(\S+) (?!K)', r'\1 -'],
    [r'^(\S+ .)(?!Q)', r'\1-'],
    [r'^(\S+ ..)(?!k)', r'\1-'],
    [r'^(\S+ ...)(?!q)', r'\1-'],
]
for d in range(1, 9):
    rules.append([str(d), '_' * d])
rules += [['/', ''], [' ', ''], [r'\Z', r'\n']]

# ---- pseudo-legal move generation ----
for r in range(8):
    for f in range(8):
        s = sq(r, f)
        for dirs, pcs in ((ORTHO, 'RQ'), (DIAG, 'BQ')):
            for dr, df in dirs:
                path = []
                k = 1
                while onb(r + dr * k, f + df * k):
                    t = sq(r + dr * k, f + df * k)
                    cls = '[' + pcs + ('K' if k == 1 else '') + ']'
                    conds = {s: cls, t: TARGET}
                    for p in path:
                        conds[p] = '_'
                    rules.append(make_rule(conds, {s: '_', t: ('copy', s), EP: '-'}))
                    path.append(t)
                    k += 1
        for dr, df in KN:
            if onb(r + dr, f + df):
                t = sq(r + dr, f + df)
                rules.append(make_rule({s: 'N', t: TARGET}, {s: '_', t: 'N', EP: '-'}))
        if 1 <= r <= 6:
            pc = 'Q' if r == 1 else 'P'
            t = sq(r - 1, f)
            rules.append(make_rule({s: 'P', t: '_'}, {s: '_', t: pc, EP: '-'}))
            if r == 6:
                t2 = sq(r - 2, f)
                rules.append(make_rule({s: 'P', t: '_', t2: '_'},
                                       {s: '_', t2: 'P', EP: 'abcdefgh'[f]}))
            for df in (-1, 1):
                if onb(r - 1, f + df):
                    t = sq(r - 1, f + df)
                    rules.append(make_rule({s: 'P', t: '[pnbrq]'}, {s: '_', t: pc, EP: '-'}))
            if r == 3:
                for df in (-1, 1):
                    if onb(r, f + df):
                        ef = f + df
                        rules.append(make_rule(
                            {s: 'P', sq(2, ef): '_', sq(3, ef): 'p', EP: 'abcdefgh'[ef]},
                            {s: '_', sq(2, ef): 'P', sq(3, ef): '_', EP: '-'}))
# castling: X = vacated king square, Y = rook square (both must be unattacked)
rules.append(make_rule({60: 'K', 61: '_', 62: '_', 63: 'R', 64: 'K'},
                       {60: 'X', 61: 'Y', 62: 'K', 63: '_', EP: '-'}))
rules.append(make_rule({60: 'K', 59: '_', 58: '_', 57: '_', 56: 'R', 65: 'Q'},
                       {60: 'X', 59: 'Y', 58: 'K', 57: '_', 56: '_', EP: '-'}))
rules.append([r'^[^\n]*\n', ''])  # drop source line

# ---- legality filter: delete lines where a K/X/Y square is attacked ----
for r in range(8):
    for f in range(8):
        k = sq(r, f)
        alts = []
        for dr, df in KN:
            if onb(r + dr, f + df):
                alts.append(anchored({sq(r + dr, f + df): 'n'}))
        for dr, df in ORTHO + DIAG:
            if onb(r + dr, f + df):
                alts.append(anchored({sq(r + dr, f + df): 'k'}))
        for df in (-1, 1):
            if onb(r - 1, f + df):
                alts.append(anchored({sq(r - 1, f + df): 'p'}))
        for dirs, pcs in ((ORTHO, '[qr]'), (DIAG, '[qb]')):
            for dr, df in dirs:
                path = []
                j = 1
                while onb(r + dr * j, f + df * j):
                    p = sq(r + dr * j, f + df * j)
                    c = {p: pcs}
                    for x in path:
                        c[x] = '_'
                    alts.append(anchored(c))
                    path.append(p)
                    j += 1
        rules.append(['(?m)^(?=.{%d}[KXY])(?=%s)[^\\n]*\\n' % (k, '|'.join(alts)), ''])

# ---- cleanup phantoms and castling rights ----
rules += [['X', '_'], ['Y', 'R']]
rules += [
    [r'(?m)^(?!.{60}K)(.{64})..', r'\g<1>--'],
    [r'(?m)^(?!.{63}R)(.{64}).', r'\g<1>-'],
    [r'(?m)^(?!.{56}R)(.{65}).', r'\g<1>-'],
    [r'(?m)^(?!.{4}k)(.{66})..', r'\g<1>--'],
    [r'(?m)^(?!.{7}r)(.{66}).', r'\g<1>-'],
    [r'(?m)^(?!r)(.{67}).', r'\g<1>-'],
]
# ---- format back to FEN ----
rules.append([r'(?m)^' + r'(.{8})' * 8 + r'(.{4})(.)$',
              r'\1/\2/\3/\4/\5/\6/\7/\8 b \9 \g<10> 0 0'])
rules.append([r'(?m) ([a-h]) 0 0$', r' \g<1>3 0 0'])
for _ in range(4):
    rules.append([r'(?m)^(\S+ b [KQkq]*)-([KQkq-]* )', r'\1\2'])
rules.append([r'(?m)^(\S+ b)  ', r'\1 - '])
for d in range(8, 0, -1):
    rules.append(['_' * d, str(d)])
rules.append([r'\n\Z', ''])

json.dump(rules, open(OUT, 'w'))
print(len(rules), os.path.getsize(OUT))
